'use client'
import {useEffect,useMemo,useState} from 'react'
import styles from './TeamBundles.module.css'
import {bundleStats} from '../lib/bundleStats.mjs'
function requestLink(bundle){const subject=`I'd like ${bundle.team} — ${bundle.id}`;const body=`Hi Evan,\n\nI'd like to purchase ${bundle.team} ${bundle.name} (${bundle.id}) for $20 plus shipping.\n\nPlease confirm availability and quote shipping to my ZIP code: \n\nThanks!`;return 'mailto:eeteecards@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}
function Photo({card,side='front'}){const [failed,setFailed]=useState(false);return !failed&&card?.[side]?<img src={card[side]} alt={`${card.year} ${card.set} ${card.player}, ${side}`} loading="lazy" onError={()=>setFailed(true)}/>:<div className={styles.placeholder}>eetee.cards<br/>{card?.player}</div>}
export default function TeamBundles({inventory}){
 const [team,setTeam]=useState(''),[open,setOpen]=useState(null),[back,setBack]=useState(false)
 useEffect(()=>{if(open)document.getElementById('bundle-contents')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})},[open])
 const bundles=useMemo(()=>inventory.bundles.filter(b=>b.team===team),[inventory,team])
 const counts=useMemo(()=>Object.fromEntries(inventory.teams.map(t=>[t,inventory.bundles.filter(b=>b.team===t).length])),[inventory])
 const feature=inventory.bundles.find(b=>b.team==='San Francisco 49ers')||inventory.bundles[0]
 const heroCards=Array.from(new Map((feature?.cards||[]).map(c=>[c.player,c])).values()).slice(0,5)
 function choose(t){setTeam(t);setOpen(null);setBack(false)}
 return <div className={styles.site}>
  <header className={styles.header}><a href="/" className={styles.brand}><img src="/eetee-logo.png" alt=""/>eetee<span>.cards</span></a><a href="#bundles">Find your team <span>↗</span></a></header>
  <section className={styles.hero}><div><p className={styles.eyebrow}>REAL CARDS. YOUR TEAM. ONE GOOD STACK.</p><h1>A little more<br/>of <em>your team.</em></h1><p className={styles.intro}>Rookies, familiar favorites, and a few new additions. Handpicked team sets from a collector’s collection, with the exact cards shown.</p><a href="#bundles" className={styles.primary}>Choose your team <span>↓</span></a><div className={styles.heroFacts}><strong>$20</strong> per bundle <span>·</span> $30+ in value in each set! <span>·</span> Shipping extra</div></div><div className={styles.heroStack} aria-label="A selection from a real team bundle">{heroCards.map((c,n)=><div key={c.id} style={{'--rotation':`${(n-2)*8}deg`,'--offset':`${(n-2)*54}px`,'--layer':n}}><Photo card={c}/></div>)}</div></section>
  <section id="bundles" className={styles.shop}>
   <div className={styles.sectionHeading}><div><p className={styles.eyebrow}>PICK YOUR SIDE</p><h2>Find your next team set.</h2></div><p>No mystery lots. No duplicates in a set.<br/>Just a good mix of your team.</p></div>
   <div className={styles.teamPicker}><label htmlFor="team-select">Your NFL team</label><select id="team-select" value={team} onChange={e=>choose(e.target.value)}><option value="">Select a team…</option>{inventory.teams.map(t=><option key={t} value={t}>{t} · {counts[t]} {counts[t]===1?'set':'sets'}</option>)}</select><span>{team?`${bundles.length} curated ${bundles.length===1?'set':'sets'} for ${team}`:`${inventory.bundles.length} curated sets across ${inventory.teams.filter(t=>counts[t]).length} teams`}</span></div>
   {!team?<div className={styles.pickPrompt}><h3>The collection starts with your colors.</h3><p>Choose a team above to see its available sets and every card inside.</p><div className={styles.quickTeams}>{['San Francisco 49ers','Seattle Seahawks','Dallas Cowboys','Buffalo Bills','New England Patriots','Green Bay Packers'].filter(t=>counts[t]).map(t=><button key={t} onClick={()=>choose(t)}>{t} <span>→</span></button>)}</div></div>:!bundles.length?<div className={styles.pickPrompt}><h3>More {team} cards to come.</h3><p>We’re collecting enough distinct cards for a complete team set. Check back for this team.</p><a href="mailto:eeteecards@gmail.com">Ask Evan about your team ↗</a></div>:<><div className={styles.teamHeading}><h3>{team}</h3><span>Every set is a separate physical lot.</span></div><div className={styles.bundleGrid}>{bundles.map(bundle=>{const stats=bundleStats(bundle.cards);const showcase=Array.from(new Map(bundle.cards.map(c=>[c.player,c])).values()).slice(0,6);return <article className={styles.bundle} key={bundle.id}><div className={styles.bundlePhotos}>{showcase.map(c=><div key={c.id}><Photo card={c}/></div>)}</div><div className={styles.bundleBody}><h4 className={styles.setLabel}>{bundle.name}</h4><dl className={styles.bundleStats}><div className={styles.prominentStat}><dt>Cards</dt><dd>{bundle.cards.length}</dd></div><div className={styles.prominentStat}><dt>Players</dt><dd>{bundle.playerCount}</dd></div><div><dt>Rookie Cards</dt><dd>{stats.rookies}</dd></div><div><dt>Inserts</dt><dd>{stats.inserts}</dd></div><div><dt>Parallels</dt><dd>{stats.parallels}</dd></div><div><dt>Vintage (Pre-2000)</dt><dd>{stats.vintage}</dd></div></dl><div className={styles.value}><strong>$30+ in value in each set!</strong></div><div className={styles.price}><strong>$20</strong><span>+ shipping</span></div><button className={styles.contentsButton} aria-expanded={open===bundle.id} onClick={()=>{setOpen(open===bundle.id?null:bundle.id);setBack(false)}}>{open===bundle.id?'Hide cards':'See every card'} <span>{open===bundle.id?'−':'+'}</span></button><a className={styles.request} href={requestLink(bundle)}>Request this bundle <span>↗</span></a><small>{bundle.id}</small></div></article>})}</div>
   {open&&(()=>{const bundle=bundles.find(b=>b.id===open);if(!bundle)return null;return <section id="bundle-contents" className={styles.contents} aria-label={`${bundle.name} contents`}><div className={styles.contentsHeading}><div><p className={styles.eyebrow}>EXACT CARDS IN THIS LOT</p><h3>{team} · {bundle.name}</h3><p>{bundle.cards.length} distinct cards · $30+ in value · $20 + shipping</p></div><button aria-pressed={back} onClick={()=>setBack(b=>!b)}>{back?'Show fronts':'Show backs'}</button></div><div className={styles.cardGrid}>{bundle.cards.map(c=><article key={c.id}><a href={back?c.back:c.front} target="_blank" rel="noreferrer" aria-label={`Enlarge ${c.player} card`}><Photo card={c} side={back?'back':'front'}/></a><h4>{c.player}</h4><p>{c.year} {c.set} · #{c.number}</p><p>{[c.family,c.parallel,c.serial,c.rookie?'Rookie':''].filter(Boolean).join(' · ')}</p></article>)}</div><a className={styles.request} href={requestLink(bundle)}>Request {bundle.name} · $20 + shipping ↗</a></section>})()}
   </>}
  </section>
  <section className={styles.how}><div><span>01</span><h3>Pick your team.</h3><p>Choose a curated lot and browse the exact fronts and backs.</p></div><div><span>02</span><h3>Know what’s inside.</h3><p>Each set includes $30+ in value, with a mix of rookies, inserts, parallels, and familiar favorites.</p></div><div><span>03</span><h3>Make it yours.</h3><p>Request your bundle by email. Evan confirms availability, shipping, and payment details before purchase.</p></div></section>
  <footer className={styles.footer}><div><a href="/" className={styles.brand}>eetee<span>.cards</span></a><p>A collector’s collection. Ready for yours.</p></div><div><a href="mailto:eeteecards@gmail.com">eeteecards@gmail.com ↗</a><p>US shipping quoted before payment. Each lot available once.<br/>Values reflect seller estimates, not guaranteed market value.</p><a href="/privacy">Privacy</a></div></footer>
 </div>
}
